from dataclasses import dataclass


@dataclass(frozen=True)
class PuckState:
    position: int
    velocity: int
    marker: int


def advance_puck(state, limit, ticks=1):
    if not isinstance(state, PuckState):
        raise TypeError("state must be a PuckState")
    if isinstance(limit, bool) or not isinstance(limit, int):
        raise TypeError("limit must be an integer")
    if isinstance(ticks, bool) or not isinstance(ticks, int):
        raise TypeError("ticks must be an integer")
    if limit <= 0:
        raise ValueError("limit must be positive")
    if ticks < 0:
        raise ValueError("ticks must be non-negative")
    if not 0 <= state.position <= limit:
        raise ValueError("position is outside the track")
    if not 1 <= state.marker <= 6:
        raise ValueError("marker must be between 1 and 6")
    if any(isinstance(value, bool) or not isinstance(value, int)
           for value in (state.position, state.velocity, state.marker)):
        raise TypeError("state fields must be integers")

    position, velocity, marker = state.position, state.velocity, state.marker
    for _ in range(ticks):
        position += velocity
        while position < 0 or position > limit:
            if position < 0:
                position = -position
            elif position > limit:
                position = 2 * limit - position
        if velocity:
            marker = (marker - 1 + abs(velocity)) % 6 + 1
            velocity += -1 if velocity > 0 else 1
    return PuckState(position, velocity, marker)

